node -e "
const crypto = require('crypto');
const db = require('better-sqlite3')('/workspace/world.db');

const reminderId = crypto.randomUUID();
const content = 'Aurora Smart Desk Lamp Pro (PROD-73FAB4) — Price: \$88.00 | In Stock: Yes (24 units) | Warranty: 12 months | Return Window: 30 days';
const now = Date.now() / 1000;  // current epoch seconds
const createdAt = '2026-09-02T10:00:00';
const creationTimestamp = new Date('2026-09-02T10:00:00Z').getTime() / 1000;

db.prepare(
  'INSERT INTO ts_reminders (reminder_id, content, creation_timestamp, reminder_timestamp, created_at) VALUES (?, ?, ?, ?, ?)'
).run(reminderId, content, creationTimestamp, creationTimestamp, createdAt);

// Verify
const row = db.prepare('SELECT * FROM ts_reminders WHERE reminder_id = ?').get(reminderId);
console.log('=== REMINDER CREATED ===');
console.log(JSON.stringify(row, null, 2));
"
